solution:
const form = { email: "test@test.com", password: "12345", confirm: "12345" }
const errors = {
  email: !form.email || !form.email.includes("@") ? "Invalid email" : null,
  password: form.password.length < 6 ? "Too short" : null,
  confirm: form.password !== form.confirm ? "Mismatch" : null
}
return errors
